# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">EXPRESSING INTERESTS, HOBBIES &amp; PREFERENCES</text>\n  <rect x="30" y="50" width="305" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="182" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Talking About Interests &amp; Passions</text>\n  <text x="45" y="103" font-size="11.5" fill="#334155">• be keen on + V-ing / Noun (hevesli olmak)</text>\n  <text x="45" y="126" font-size="11.5" fill="#334155">• be fond of + V-ing / Noun (düşkün olmak)</text>\n  <text x="45" y="149" font-size="11.5" fill="#334155">• be interested in + V-ing / Noun (ilgi duymak)</text>\n  <text x="45" y="172" font-size="11.5" fill="#334155">• be into / crazy about + V-ing / Noun</text>\n  <text x="45" y="195" font-size="11.5" fill="#334155">• can\'t stand + V-ing (تحammül edememek)</text>\n  <text x="182" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">Prepositions (on, of, in, into, about) + V-ing!</text>\n  <rect x="365" y="50" width="305" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="517" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Stating Preferences (Tercih Yapıları)</text>\n  <text x="380" y="105" font-size="11.5" font-weight="bold" fill="#166534">1) prefer + V-ing + to + V-ing:</text>\n  <text x="390" y="123" font-size="11" fill="#334155">&quot;I prefer playing chess to watching TV.&quot;</text>\n  <text x="380" y="150" font-size="11.5" font-weight="bold" fill="#166534">2) would rather + V1 + than + V1:</text>\n  <text x="390" y="168" font-size="11" fill="#334155">&quot;I would rather paint than take photos.&quot;</text>\n  <text x="380" y="195" font-size="11.5" font-weight="bold" fill="#166534">3) would prefer + to V1 + rather than + V1:</text>\n  <text x="390" y="213" font-size="11" fill="#334155">&quot;She\'d prefer to read a novel rather than sleep.&quot;</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">PRESENT AND PAST ABILITIES: CAN, COULD &amp; BE ABLE TO</text>\n  <rect x="25" y="50" width="205" height="185" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="127" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Present Ability (Şimdi)</text>\n  <text x="40" y="105" font-size="11" fill="#334155">• can / am-is-are able to + V1</text>\n  <text x="40" y="130" font-size="11" fill="#475569">&quot;He can speak three languages.&quot;</text>\n  <text x="40" y="158" font-size="11" fill="#334155">• be gifted in / talented at +</text>\n  <text x="50" y="176" font-size="11" fill="#475569">V-ing / Noun (yetenekli olmak)</text>\n  <text x="40" y="200" font-size="11" fill="#475569">&quot;She is gifted in playing violin.&quot;</text>\n  <rect x="247" y="50" width="205" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="350" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">General Past Ability: COULD</text>\n  <text x="262" y="105" font-size="11" fill="#334155">• Geçmişteki genel yetenekler:</text>\n  <text x="262" y="128" font-size="11" fill="#1e40af" font-weight="bold">could + V1</text>\n  <text x="262" y="152" font-size="11" fill="#334155">&quot;Mozart could compose music</text>\n  <text x="262" y="170" font-size="11" fill="#334155">when he was five years old.&quot;</text>\n  <text x="262" y="200" font-size="10.5" fill="#475569">Olumsuzda her durumda:</text>\n  <text x="262" y="216" font-size="10.5" font-weight="bold" fill="#1e40af">couldn\'t = wasn\'t/weren\'t able to</text>\n  <rect x="470" y="50" width="205" height="185" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="572" y="75" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#b91c1c">Specific Past Achievement</text>\n  <text x="485" y="105" font-size="11" fill="#334155">• Geçmişte zor bir durumu tek</text>\n  <text x="495" y="122" font-size="10.5" fill="#475569">seferde başarma (managed to):</text>\n  <text x="485" y="145" font-size="11" font-weight="bold" fill="#991b1c">was / were able to + V1</text>\n  <text x="485" y="168" font-size="10.5" fill="#334155">&quot;Despite the heavy rain, they</text>\n  <text x="485" y="185" font-size="10.5" fill="#334155">were able to reach the summit.&quot;</text>\n  <text x="485" y="212" font-size="10.5" font-weight="bold" fill="#b91c1c">(Bu durumda \'could\' kullanılmaz!)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">WRITING A PARAGRAPH / ESSAY ABOUT INTERESTS &amp; TALENTS</text>\n  <rect x="35" y="55" width="300" height="175" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="185" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Structure &amp; Linking Words</text>\n  <text x="50" y="108" font-size="11.5" fill="#334155">• Topic Sentence: Ana ilgi alanını tanıtma</text>\n  <text x="50" y="132" font-size="11.5" fill="#334155">• Addition (Ekleme): both ... and, not only ...</text>\n  <text x="62" y="150" font-size="11" fill="#475569">but also, as well as, in addition, furthermore</text>\n  <text x="50" y="175" font-size="11.5" fill="#334155">• Reason &amp; Result: because, since, therefore,</text>\n  <text x="62" y="193" font-size="11" fill="#475569">so that, in order to improve my skills</text>\n  <rect x="365" y="55" width="300" height="175" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="515" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Club Application &amp; Profile Vocabulary</text>\n  <text x="380" y="108" font-size="11.5" fill="#334155">• extracurricular activities (ders dışı etkinlikler)</text>\n  <text x="380" y="132" font-size="11.5" fill="#334155">• pursue a hobby / passion (bir tutkunun peşinden</text>\n  <text x="392" y="150" font-size="11" fill="#475569">gitmek) · master a skill (bir beceride ustalaşmak)</text>\n  <text x="380" y="175" font-size="11.5" fill="#334155">• broaden horizons (ufkunu genişletmek)</text>\n  <text x="380" y="200" font-size="11.5" fill="#334155">• boost self-confidence (özgüveni artırmak)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
